{"implementation":"def solve(case):
    import math

    # Extract and validate required fields
    payload = case.get('payload', {})
    required = ['sentence_vectors', 'query_vector', 'context_weight']
    for field in required:
        if field not in payload:
            raise ValueError(f"Missing required field: {field}")

    sentence_vectors = payload['sentence_vectors']
    query_vector = payload['query_vector']
    context_weight = payload['context_weight']

    # Validate types and non-empty
    if not isinstance(sentence_vectors, list) or len(sentence_vectors) == 0:
        raise ValueError("sentence_vectors must be a non-empty list")
    if not isinstance(query_vector, list) or len(query_vector) == 0:
        raise ValueError("query_vector must be a non-empty list")
    if not isinstance(context_weight, (int, float)):
        raise ValueError("context_weight must be a number")

    n = len(sentence_vectors)
    dim = len(query_vector)
    for i, sv in enumerate(sentence_vectors):
        if not isinstance(sv, list) or len(sv) != dim:
            raise ValueError(f"sentence_vectors[{i}] has invalid dimensions")
        for val in sv:
            if not isinstance(val, (int, float)):
                raise ValueError(f"sentence_vectors[{i}] contains non-numeric value")
    for val in query_vector:
        if not isinstance(val, (int, float)):
            raise ValueError("query_vector contains non-numeric value")

    # Compute cosine similarities
    similarities = []
    for sv in sentence_vectors:
        dot = sum(a*b for a,b in zip(sv, query_vector))
        norm_sv = math.sqrt(sum(a*a for a in sv))
        norm_q = math.sqrt(sum(b*b for b in query_vector))
        if norm_sv == 0.0 or norm_q == 0.0:
            sim = 0.0
        else:
            sim = dot / (norm_sv * norm_q)
        similarities.append(sim)

    # Compute neighbor averages
    neighbor_avgs = []
    for i in range(n):
        if n == 1:
            neighbor_avgs.append(0.0)
        elif i == 0:
            neighbor_avgs.append(similarities[1])
        elif i == n-1:
            neighbor_avgs.append(similarities[n-2])
        else:
            neighbor_avgs.append((similarities[i-1] + similarities[i+1]) / 2.0)

    # Blend and round
    final_scores = []
    for own, nbr in zip(similarities, neighbor_avgs):
        blended = (1 - context_weight) * own + context_weight * nbr
        # Round to 10 decimal places to avoid floating point noise
        rounded = round(blended, 10)
        final_scores.append(rounded)

    # Build ranking: descending score, then ascending index
    indexed = [(final_scores[i], i) for i in range(n)]
    indexed.sort(key=lambda x: (-x[0], x[1]))
    ranking = [idx for _, idx in indexed]

    # Return JSON-serializable result
    return {
        "scores": final_scores,
        "neighbor_averages": neighbor_avgs,
        "ranking": ranking
    }
"}
